-- A simple signal. (A BindableEvent would hand listeners a COPY of the
-- data table, so their changes wouldn't save. This passes the real table.)
local loadedCallbacks = {}

local DataManager = {}
DataManager.Loaded = {
	Connect = function(_, callback)
		table.insert(loadedCallbacks, callback)
	end,
}

local function fireLoaded(player, data)
	for _, callback in ipairs(loadedCallbacks) do
		task.spawn(callback, player, data)
	end
end

